Tool response:
Tool: bulk_enroll_students
Description: Bulk enroll students into a course cohort with pending-verification status.
Parameters:
    {
      "type": "object",
      "properties": {
        "course_id": {
          "type": "string",
          "title": "Course Id"
        },
        "cohort_id": {
          "type": "string",
          "title": "Cohort Id"
        },
        "student_ids": {
          "items": {
            "type": "string"
          },
          "type": "array",
          "title": "Student Ids"
        }
      },
      "required": [
        "course_id",
        "cohort_id",
        "student_ids"
      ]
    }
